"use client";

import { Save, Lock, Globe } from "lucide-react";

export default function SettingsPage() {
    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight text-gray-900">Settings</h1>
                    <p className="text-sm text-gray-500">System configuration and preferences.</p>
                </div>
                <button className="inline-flex items-center justify-center gap-2 rounded-lg bg-black px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-gray-800">
                    <Save className="h-4 w-4" />
                    Save Changes
                </button>
            </div>

            <div className="rounded-xl border bg-white p-6 shadow-sm">
                <h3 className="mb-4 flex items-center gap-2 text-lg font-semibold text-gray-900">
                    <Globe className="h-5 w-5 text-gray-500" />
                    SEO Configuration
                </h3>
                <div className="grid gap-6 md:grid-cols-2">
                    <div>
                        <label className="mb-2 block text-sm font-medium text-gray-700">Site Name</label>
                        <input
                            type="text"
                            defaultValue="Integral Labs"
                            className="w-full rounded-lg border border-gray-300 p-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <div>
                        <label className="mb-2 block text-sm font-medium text-gray-700">Default Title Suffix</label>
                        <input
                            type="text"
                            defaultValue="| Integral Labs"
                            className="w-full rounded-lg border border-gray-300 p-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <div className="md:col-span-2">
                        <label className="mb-2 block text-sm font-medium text-gray-700">Default Description</label>
                        <textarea
                            rows={2}
                            defaultValue="Top-tier digital solutions for bold businesses."
                            className="w-full rounded-lg border border-gray-300 p-2 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                </div>
            </div>

            <div className="rounded-xl border bg-white p-6 shadow-sm">
                <h3 className="mb-4 flex items-center gap-2 text-lg font-semibold text-gray-900">
                    <Lock className="h-5 w-5 text-gray-500" />
                    Security
                </h3>
                <div className="space-y-4">
                    <div className="flex items-center justify-between rounded-lg border bg-gray-50 p-4">
                        <div>
                            <h4 className="text-sm font-medium text-gray-900">Admin Password</h4>
                            <p className="text-xs text-gray-500">Last changed 30 days ago</p>
                        </div>
                        <button className="text-sm font-medium text-blue-600 hover:underline">Change</button>
                    </div>
                    <div className="flex items-center justify-between rounded-lg border bg-gray-50 p-4">
                        <div>
                            <h4 className="text-sm font-medium text-gray-900">Two-Factor Auth</h4>
                            <p className="text-xs text-gray-500">Currently disabled</p>
                        </div>
                        <button className="text-sm font-medium text-blue-600 hover:underline">Enable</button>
                    </div>
                </div>
            </div>
        </div>
    );
}
